apiVersion: apps/v1
kind: Deployment
metadata: { name: web }
spec:
  replicas: 3
  selector: { matchLabels: { app: web } }
  template:
    metadata: { labels: { app: web } }
    spec:
      containers:
        - name: web
          image: myregistry/web:1.4
          ports: [{ containerPort: 8000 }]
          readinessProbe: { httpGet: { path: /health, port: 8000 } }
          resources: { requests: { cpu: 100m, memory: 128Mi }, limits: { memory: 256Mi } }
---
apiVersion: v1
kind: Service
metadata: { name: web }
spec:
  selector: { app: web }
  ports: [{ port: 80, targetPort: 8000 }]

kubectl apply -f web.yaml; kubectl get pods; kubectl rollout status deployment/web; kubectl rollout undo deployment/web

provider "azurerm" { features {} }
resource "azurerm_resource_group" "rg" {
  name     = "rg-shop-dev"
  location = "centralindia"
}

terraform init     # download providers, set up backend
terraform plan     # show what will change
terraform apply    # make the changes
terraform destroy  # remove everything (careful!)

Terraform keeps a **state file** mapping code to real resources. Store state in a **remote backend** with **locking** (e.g. a cloud storage backend), restrict access (it may contain sensitive values), and never edit it by hand. Reuse patterns with **modules**.
